// Junta cotizacion + criterios + solicitud en un objeto plano para el resto del flujo.
const q = $('Data Table - Leer cotización').first().json || {};
const c = $('Data Table - Leer criterios').first().json || {};
const s = $('Data Table - Leer solicitud').first().json || {};
const { id: _qi, createdAt: _qc, updatedAt: _qu, ...quote } = q;
const { id: _ci, createdAt: _cc, updatedAt: _cu, ...criterios } = c;
const { id: _si, createdAt: _sc, updatedAt: _su, ...solicitud } = s;
return { json: {
  id_solicitud: quote.id_solicitud || criterios.id_solicitud || null,
  servicio: quote.servicio || criterios.servicio || '',
  estado: quote.estado || '',
  total_registros: quote.total_registros,
  valor: quote.valor, iva: quote.iva, valor_total: quote.valor_total,
  pdf_url: quote.pdf_url || null,
  ronda_correccion: Number(quote.ronda_correccion) || 0,
  nombre_cliente: solicitud.nombre_cliente || criterios.nombre_solicitante || '',
  razon_social: criterios.razon_social || '',
  email_cliente: solicitud.email_cliente || '',
  criterios, solicitud
} };

// Arma el texto markdown del mensaje de Teams (el formulario colapsa \n simple: hace falta \n\n).
// Mensaje simple con link a la página de revisión propia (reemplaza el formulario interactivo de Teams).
const d = $json;
const fmt = (n) => Number(n || 0).toLocaleString('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 });
const link = 'https://revision-propuesta-ccb.vercel.app/?id_solicitud=' + encodeURIComponent(d.id_solicitud);
const mensaje = '📋 <b>Nueva propuesta para revisar</b><br><br>'
  + 'Cliente: ' + (d.nombre_cliente || '(sin nombre)') + '<br>'
  + 'Empresa: ' + (d.razon_social || '-') + '<br>'
  + 'Servicio: ' + (d.servicio || '-') + '<br>'
  + 'Valor: ' + fmt(d.valor_total) + '<br><br>'
  + '<a href="' + link + '">👉 Ver y decidir</a>';
return { json: { ...d, mensaje_teams: mensaje } };

const j = $json;
const flujo = $workflow.name;
const nodoFallido = 'Teams - Notificar y Esperar Decisión';
const tipoError = (j.error && (j.error.name || j.error.type)) || 'Error técnico';
const mensaje = (j.error && (j.error.message || j.error.description)) || 'Fallo técnico del nodo Teams (sendAndWait)';
const id = $('Consolidar datos de la propuesta').first().json.id_solicitud;
const fechaError = DateTime.now().setZone('America/Bogota').toFormat('yyyy-MM-dd HH:mm:ss');
const emailBody = `<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background-color:#F2F5F9;font-family:Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#F2F5F9"><tr><td align="center" style="padding:32px 16px;">
<table width="600" cellpadding="0" cellspacing="0" border="0" bgcolor="#FFFFFF" style="max-width:600px;border-radius:12px;overflow:hidden;">
<tr><td bgcolor="#001489" align="center" style="padding:28px 40px;">
<p style="font-size:11px;font-weight:600;color:rgba(255,255,255,0.65);text-transform:uppercase;letter-spacing:3px;margin:0;">Servicios de Información</p>
</td></tr>
<tr><td bgcolor="#D64545" align="center" style="padding:11px 32px;">
<p style="font-size:12px;font-weight:700;color:#FFFFFF;text-transform:uppercase;letter-spacing:2px;margin:0;">⚠️ La fila quedó en REVISION_MANUAL</p>
</td></tr>
<tr><td bgcolor="#FFFFFF" style="padding:32px 40px;">
<p style="font-size:14px;color:#404e4f;margin:0 0 16px 0;line-height:1.7;">El nodo de Teams falló técnicamente al notificar/esperar la decisión. La fila se marca REVISION_MANUAL para que no quede huérfana.</p>
<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Flujo:</strong> ${flujo}</p>
<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Tipo de error:</strong> ${tipoError}</p>
<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Nodo fallido:</strong> ${nodoFallido}</p>
<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">Mensaje de error:</strong> ${mensaje}</p>
<p style="font-size:13px;color:#212120;margin:0 0 6px 0;"><strong style="color:#001489;">ID solicitud:</strong> ${id}</p>
<p style="font-size:13px;color:#212120;margin:0;"><strong style="color:#001489;">Fecha:</strong> ${fechaError}</p>
</td></tr>
</table></td></tr></table></body></html>`;
return { json: { id_solicitud: id, flujo, tipo_error: tipoError, workflow_origen: 'W4-B-aprobacion-teams', nodo_fallido: nodoFallido, mensaje_error: mensaje, emailBody } };

// Patrón de error estándar del pipeline.
const mensaje = 'Falta id_solicitud en la solicitud recibida por W4-B.';
const emailBody = '<p>Error al notificar la propuesta para revisión en Teams.</p><ul><li><b>Detalle:</b> ' + mensaje + '</li></ul>';
return { json: { id_solicitud: '', workflow_origen: 'W4-B-aprobacion-teams', nodo_fallido: 'Validar id_solicitud presente', mensaje_error: mensaje, emailBody } };

